from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro="Smoking touches <strong>Crohn's disease</strong> and <strong>ulcerative colitis</strong> differently in research, yet quitting remains a health priority for nearly everyone with IBD. This page explains nuance without promoting tobacco, covers quitting supports, and addresses vaping questions. Education only.",
        sections=[("Crohn's disease and smoking data", ["Smoking links to higher Crohn's risk, more flares, fistula complications, and postoperative recurrence in many studies.", 'Quitting improves surgical outcomes and may reduce flare frequency over time.', 'Former smokers still need standard IBD care; damage is not always instantly reversible.', 'Bring honest pack year history to preoperative visits.']), ('Ulcerative colitis nuance without tobacco advice', ['Historical studies noted lower UC diagnosis rates among current smokers, which is not a reason to start or continue smoking.', 'Smoking harms lungs, bones, cardiovascular health, and cancer risk, and complicates healing.', 'Quitting may shift UC symptoms; clinicians can adjust medicines during cessation.', 'Never trade lung health for colon symptom tricks.']), ('Nicotine replacement and prescriptions', ['Patches, gum, lozenges, and prescription quit aids can be discussed with GI and primary care to limit interactions.', 'List all nicotine products including pouches and vaping liquids at appointments.', 'Dosing schedules may align with work breaks to reduce withdrawal irritability.', 'Pregnancy and breastfeeding require specialized quit plans.']), ('Vaping and heated products', ['Vaping is not harmless for lungs or surgery recovery; IBD specific outcome data remain limited.', 'Teams usually prefer evidence based quit programs over trading cigarettes for chronic vaping.', 'Flavoring chemicals carry their own lung stories; do not assume safety.', 'If you vape THC where legal, separate medical discussions from nicotine plans.']), ('Cannabis smoking overlap', ['Some patients use cannabis for symptoms where legal; inhaled cannabis still carries respiratory risks separate from inflammation control.', 'Discuss forms, doses, and legal context honestly with your team.', 'Edible forms may affect nausea differently than smoked forms.', 'Driving laws apply regardless of medical use claims.']), ('Surgery, wounds, and biologics', ['Smokers face higher infection and anastomotic complication rates for some bowel surgeries.', 'Quitting before elective surgery when possible is a common preoperative goal.', 'Wound healing slows; surgeons may delay cases until cessation plans start.', 'Biologic timing continues during quit attempts unless anesthesia plans say otherwise.']), ('Bone health and steroids plus smoking', ['Smoking and steroids both threaten bone density; dual exposure deserves DEXA conversations.', 'Calcium and vitamin D supplementation may increase when teams agree.', 'Weight bearing exercise helps when joints allow; see fitness education pages.', 'Fall prevention matters when osteoporosis appears.']), ('Behavioral supports that stick', ['Quit lines, apps, group counseling, and relapse plans beat willpower alone.', 'Identify triggers such as alcohol nights, work stress, or social smoking patios.', 'Replace rituals with walks, gum, or fidget tools during the first month.', 'Celebrate smoke free weeks without shaming slips; restart quickly.']), ('Talking with family and coworkers', ['Household smokers complicate quit attempts; negotiate smoke free cars and balconies.', 'Coworkers may offer cigarettes socially; rehearse polite refusals.', 'Kids benefit when parents quit; pediatricians support family plans.', 'Privacy about quit attempts is fine; you owe no workplace announcement.']), ('Withdrawal and gut symptoms', ['Nicotine withdrawal can irritate mood and sleep, indirectly affecting gut sensation.', 'Some UC patients report symptom shifts after quitting; log stools to separate withdrawal from flare.', 'Do not assume every change is a flare requiring steroids without messaging clinic.', 'Hydration and regular meals stabilize withdrawal weeks for some people.']), ('Financial and access resources', ['Many states offer free quit kits through health departments.', 'Insurance may cover counseling and medicines with minimal copay.', 'Employer wellness programs sometimes include nicotine coaching.', 'Keep receipts if flex spending covers quit aids.']), ('When quitting feels impossible', ['Multiple quit attempts are normal; each attempt teaches trigger patterns.', 'Behavioral health can treat depression or anxiety fueling smoking.', 'Harm reduction conversations belong with clinicians, not anonymous forums alone.', 'Emergency breathing symptoms need urgent care regardless of quit status.']), ('Recording quit progress for clinic', ['Note quit date, tools used, slips, and craving times in IBDPal or a notebook.', 'Surgeons appreciate smoke free intervals measured in weeks before operations.', 'Primary care can update problem lists so every specialist sees status.', 'Victories include reduced pack count even before full cessation.']), ('Long term health after quitting', ['Cardiovascular risk falls over years after quitting.', 'Lung function may stabilize; cancer risk declines gradually.', 'IBD medicines continue as prescribed; quitting is complementary, not a substitute.', 'Annual lung screening discussions apply to heavy former smokers per primary care guidelines.']), ('Hospital smoke free policies', ['Inpatient stays require nicotine management plans to avoid withdrawal on wards.', 'Patches may be used in hospitals when ordered; ask nurses.', 'Surgery cancellations may occur if smoking continues undisclosed before anesthesia.', 'Honesty protects airway management during procedures.']), ('Smoking and medication levels', ['Smoking can affect how some medicines metabolize; levels may shift after quitting.', 'Therapeutic drug monitoring drugs might need recheck after quit date.', 'Tell infusion nurses your quit timeline.', 'Do not adjust biologic intervals yourself.']), ('Social media quit groups', ['Online groups vary in quality; prefer clinician linked programs.', 'Avoid groups shaming medications you need for IBD while quitting nicotine.', 'Share quit milestones with friends offline too.', 'Block content that triggers craving if algorithms sabotage you.']), ('Pregnancy and smoking cessation', ['Pregnancy motivates quit attempts; coordinate OB, GI, and quit coaches.', 'Some nicotine replacement options differ in pregnancy; personalize with doctors.', 'Postpartum relapse prevention plans matter after delivery stress.', 'Breastfeeding questions belong to lactation consultants with prescriber input.']), ('Dental and oral health links', ['Smoking worsens gum disease which intersects with inflammation and nutrition.', 'Dental cleanings support overall health while quitting.', 'Oral lesions should be checked promptly if you smoke or vape.', 'Dentists appreciate knowing IBD meds affecting oral tissues.']), ('Workplace smoke breaks culture', ['Former smoke break coworkers may pressure social habits; rehearse boundaries.', 'Use former break times for brief walks if mobility allows.', 'Remote workers may miss social cues that triggered smoking; build new cues.', 'Tell occupational health if secondhand smoke at job site persists.']), ('Measuring success beyond cigarettes', ['Reduced cough, improved exercise tolerance, and better wound healing are wins.', 'Track lung symptoms if you have asthma overlap.', 'Celebrate smoke free months with non food treats if food triggers are sensitive.', 'Relapse plans written in advance reduce shame spirals.']), ('Integrating quit plans with flare treatment', ['Steroid bursts may mood swing during quit; warn family and clinicians.', 'If UC symptoms shift after quit, treat inflammation medically rather than restarting tobacco.', 'Infusion day is stressful; plan extra quit support those days.', 'Journal mood and stool separately to see patterns over six weeks.']), ('Nicotine pouches and lozenges etiquette', ['Dispose pouches responsibly; discuss pouch nicotine dose with clinicians like other replacements.', 'Rotate gum and patches if mouth irritation appears.', 'Keep products away from children and pets at home.', 'Track combined nicotine intake if using multiple forms temporarily.']), ('Smoking relapse prevention cards', ['Wallet cards list three people to call, three distractions, and clinic phone numbers.', 'Relapse hours often cluster with alcohol; plan alcohol limits if triggers overlap.', 'Write why you quit on the card including surgery dates and kid names.', 'Review card after stressful clinic visits or infusions.']), ('Air quality at home', ['HEPA filters help if partners still smoke outside but residue enters windows.', 'Wash jackets that smell like smoke before closet storage.', 'Car interiors hold smoke smell; detail cleaning aids quit attempts.', 'Apartment neighbors smoking on balconies may require landlord conversations.']), ('Smoking history documentation for new GIs', ['Pack years and quit dates belong in new patient packets alongside IBD history.', 'Former smoker status still matters for surgical risk stratification.', 'Vaping history counts; list devices and nicotine strengths honestly.', 'Update problem list in patient portals after quit milestones.']), ('Celebrating smoke free milestones', ['One week, one month, and one year deserve recognition without food triggers if food is sensitive.', 'Deposit cigarette money saved into a visible jar for fitness gear or travel.', 'Tell your GI at follow ups; notes in chart help future pre op assessments.', 'Share wins with quitline coaches who tracked your start date.']), ('When partners still smoke', ['Negotiate smoke free home and car boundaries to protect your lungs and quit effort.', 'Couples counseling may help if partner smoking feels like sabotage.', 'Never use partner smoking as excuse to restart; focus on your plan.', "Children's lung health adds moral weight to household agreements."]), ('Medication counseling after quit date', ['Some IBD patients need dose reviews when smoking stops because metabolism shifts.', 'Pharmacists run interaction checks on quit aids plus azathioprine or biologics.', 'Update medication list in wallet card after any quit related prescription starts.', 'Never hide nicotine replacement use from anesthesia teams before surgery.']), ('Workplace smoke exposure documentation', ['Note dates and locations of secondhand exposure at job sites.', 'Occupational health may help relocate desks or improve ventilation.', 'Union reps can join meetings if exposure persists after requests.', 'Medical letter describing asthma or IBD lung sensitivity may support changes.']), ('Quit apps and privacy', ['Read privacy policies before linking quit apps to social networks.', 'Disable public leaderboards if comparison triggers shame.', 'Export quit date data for clinicians if apps allow.', 'Delete apps that push nicotine product ads.']), ('Skin and wound checks while quitting', ['Nicotine withdrawal does not stop need for dermatology checks on biologic exposed skin.', 'Wounds heal slower while smoking; photograph surgical sites per surgeon instructions.', 'Report new leg swelling or calf pain when activity resumes after quitting.', 'Sun protection remains important on immunosuppression regardless of smoking status.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.']), ('Integrating quit goals with infusion center routines', ['Schedule quit coaching calls on non infusion days when fatigue is lower.', 'Tell infusion nurses your quit date so they celebrate milestones during chair time.', 'Avoid scheduling quit day same week as major steroid taper if mood swings worry you.', 'Keep nicotine replacement supplies in infusion bag only if storage rules allow.', 'Even a single cigarette after weeks smoke free is a lapse, not proof that quitting is impossible forever.'])],
        clinic_quote="I want to quit smoking with my Crohn's or colitis care plan. Which nicotine replacement or prescriptions are safe with my current IBD meds, and how should we watch flare symptoms during withdrawal?",
        faqs=[('Will quitting cause a UC flare?', 'Some patients report symptom shifts; clinicians can adjust IBD meds and support gradual cessation.'), ('Is one cigarette daily harmless?', 'Even low levels carry surgical and cardiovascular risks; teams still encourage full cessation.'), ('Does secondhand smoke matter?', 'Reduce exposure when possible, especially around children and before surgery.'), ('Can I use nicotine gum forever?', 'Discuss long term gum use with clinicians; goal is usually nicotine freedom eventually.')],
        related_html=related(
            ("Surgery recovery", "/blog/ibd-surgery-recovery-nutrition"),
            ("Stress management", "/blog/stress-management-ibd"),
            ("Biologics overview", "/blog/biologics-ibd-overview"),
            ("Resources", "/resources"),
        ),
        closing=['Quitting is a medical project, not a character exam. Clinicians want to help you breathe and heal.'],
    )
